-- 2026-10-27 Master (category 3) + Legendary (category 4) mercenary tiers.
-- Idempotent: range-scoped DELETEs on the generated id bands, then INSERTs.
-- Master = same Tier I-V Journeyman x1.25; Legendary = x1.5 (hp/mana/AC/ATK/
-- dmg/accuracy/regens; healscale+spellscale +25/+50). Wiring mirrors the
-- Journeyman merchant template entries. Client dbstr additions ship separately.

DELETE FROM merc_merchant_template_entries WHERE merc_template_id >= 581;
DELETE FROM merc_templates WHERE merc_template_id >= 581;
DELETE FROM merc_stats WHERE merc_npc_type_id >= 68;
DELETE FROM merc_armorinfo WHERE merc_npc_type_id >= 68;
DELETE FROM merc_weaponinfo WHERE merc_npc_type_id >= 68;
DELETE FROM merc_spell_list_entries WHERE merc_spell_list_id BETWEEN 9 AND 16;
DELETE FROM merc_spell_lists WHERE merc_spell_list_id BETWEEN 9 AND 16;
DELETE FROM merc_stance_entries WHERE proficiency_id IN (3, 4);
DELETE FROM merc_npc_types WHERE merc_npc_type_id >= 68;
DELETE FROM merc_types WHERE merc_type_id >= 55;

